// Compatibilidade pública e falhas de recursos: sem imagens substitutas ou fallback procedural.
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import * as battle from '../src/js/toy-room/ToyRoomBattle.js';
import * as config from '../src/js/toy-room/BattleConfig.js';
import * as renderer from '../src/js/toy-room/BattleRenderer.js';
import { loadBattleManifest, loadBattleImages } from '../src/js/toy-room/BattleAssets.js';
for (const key of Object.keys(config)) assert.equal(battle[key],config[key]);
assert.equal(battle.battleAnimationFrame,renderer.battleAnimationFrame);
const manifest=JSON.parse(await fs.readFile(new URL('../assets/art/toy-room/battle/remediation/manifest.json',import.meta.url)));
const originalFetch=globalThis.fetch,originalImage=globalThis.Image;
let failedImage=false;
try {
  globalThis.fetch=async()=>({ok:false});
  await assert.rejects(loadBattleManifest(),/Não foi possível carregar o manifesto de combate/);
  globalThis.fetch=async()=>({ok:true,json:async()=>structuredClone(manifest)});
  globalThis.Image=class {set src(value){queueMicrotask(()=>failedImage?this.onerror():this.onload());}};
  const loaded=await loadBattleManifest();
  failedImage=true;
  await assert.rejects(loadBattleImages(loaded,new Map()),/Sprite de combate ausente/);
  failedImage=false;
  const missingGirl=new battle.ToyRoomBattle({assets:{get:()=>null},story:{attackFrames:[{}]}});
  await missingGirl.readyPromise;assert.equal(missingGirl.ready,false);assert.match(missingGirl.error,/sprites da menina ou do ataque de espada estão ausentes/);
  const missingSword=new battle.ToyRoomBattle({assets:{get:()=>({})},story:{attackFrames:[null]}});
  await missingSword.readyPromise;assert.equal(missingSword.ready,false);assert.match(missingSword.error,/sprites da menina ou do ataque de espada estão ausentes/);
  const valid=new battle.ToyRoomBattle({assets:{get:()=>({})},story:{attackFrames:[{}]}});
  await valid.readyPromise;assert.equal(valid.ready,true);assert.equal(valid.error,null);assert.ok(valid.images.size>0);
  const simulation=new battle.ToyRoomBattle({}, {loadAssets:false});assert.equal(simulation.ready,true);
  console.log('APROVADO: identidade dos exports; falha de manifesto/imagem; menina/espada ausentes não liberam o combate; carga válida e simulação sem imagens preservadas.');
}finally{globalThis.fetch=originalFetch;globalThis.Image=originalImage;}
